#include <cctype>
#include <string_view>

bool isStrongPassword(std::string_view password)
{
    if (password.length() < 8)
    {
        return false;
    }
    bool hasUpper{ false };
    bool hasLower{ false };
    bool hasDigit{ false };
    for (std::size_t i{ 0 }; i < password.length(); ++i)
    {
        const char c{ password[i] };
        const unsigned char u{ static_cast<unsigned char>(c) };
        if (c == ' ') return false;
        if (std::isupper(u)) hasUpper = true;
        else if (std::islower(u)) hasLower = true;
        else if (std::isdigit(u)) hasDigit = true;
    }
    return hasUpper && hasLower && hasDigit;
}

unitTests:
TEST("strong passwords") { CHECK(isStrongPassword("Tr0ubador")); CHECK(isStrongPassword("aB3defgh")); CHECK(isStrongPassword("XyZ12345!")); }
TEST("too short") { CHECK(!isStrongPassword("aB3")); CHECK(!isStrongPassword("aB3defg")); CHECK(!isStrongPassword("")); }
TEST("missing a kind of character") { CHECK(!isStrongPassword("alllowercase1")); CHECK(!isStrongPassword("ALLUPPERCASE1")); CHECK(!isStrongPassword("NoDigitsHere")); }
TEST("spaces are not allowed") { CHECK(!isStrongPassword("Has a Space 1")); }

